<?php
require_once __DIR__ . '/../app/layout.php';
$u=require_role(['ngo','demand_reporter','admin']); $pdo=db();
$area=trim($_GET['area']??'');$category=trim($_GET['category']??'');
$sql="SELECT sf.*,rest.name AS donor,rest.address AS donor_address FROM surplus_food sf JOIN users rest ON rest.id=sf.restaurant_id WHERE sf.status='available' AND sf.safety_deadline>NOW() AND EXISTS (SELECT 1 FROM food_safety_checks fsc WHERE fsc.surplus_food_id=sf.id AND fsc.result='safe')";$params=[];
if($area!==''){$sql.=' AND (sf.pickup_address LIKE ? OR rest.address LIKE ?)';$params[]='%'.$area.'%';$params[]='%'.$area.'%';}
if($category!==''){$sql.=' AND sf.category=?';$params[]=$category;}
$sql.=' ORDER BY sf.safety_deadline ASC LIMIT 200';$q=$pdo->prepare($sql);$q->execute($params);$foods=$q->fetchAll();
$myAddress=strtolower((string)($u['address']??''));
foreach($foods as &$f){$pickup=strtolower((string)$f['pickup_address'].' '.(string)$f['donor_address']);$areaMatch=false;foreach(['mirpur','uttara','dhanmondi','mohammadpur','gulshan','farmgate','motijheel','dhaka'] as $key){if(str_contains($myAddress,$key)&&str_contains($pickup,$key)){$areaMatch=true;break;}}$hours=max(0,(strtotime($f['safety_deadline'])-time())/3600);$urgency=$hours<=2?30:($hours<=6?22:($hours<=12?14:6));$score=min(100,(int)$f['priority_score']+$urgency+($areaMatch?18:0));$f['match_score']=$score;$f['area_match']=$areaMatch;}
unset($f);usort($foods,fn($a,$b)=>$b['match_score']<=>$a['match_score']);
page_header('Smart food matching'); ?>
<div class="page-intro"><div class="eyebrow">EXPLAINABLE MATCHING</div><h1>Recommended <em>food matches.</em></h1><p>Only admin-approved safe listings are considered. Scores use declared priority, time remaining and approximate address-area overlap.</p></div>
<div class="alert warning">Matching scores are rules-based recommendations, not AI predictions. Exact road distance, NGO meal capacity and volunteer availability are not available unless entered into the system.</div>
<form class="filter-bar" method="get"><input name="area" value="<?= e($area) ?>" placeholder="Filter by area / district"><select name="category"><option value="">All categories</option><?php foreach(['Rice & Biryani','Curry & Vegetables','Bakery','Fruit','Packaged food','Snacks','Other'] as $c): ?><option value="<?= e($c) ?>" <?= $category===$c?'selected':'' ?>><?= e($c) ?></option><?php endforeach; ?></select><button class="btn">Find matches</button></form>
<div class="food-grid"><?php foreach($foods as $f): ?><article class="food-card"><div class="food-card-art"><span class="food-category"><?= e($f['category']) ?></span><img class="food-photo" loading="lazy" src="<?= e(food_image_url($f)) ?>" alt="<?= e($f['food_name']) ?>"></div><div class="food-card-body"><div class="food-title-row"><h3><?= e($f['food_name']) ?></h3><span class="badge good"><?= (int)$f['match_score'] ?>% match</span></div><p><?= e($f['description']) ?></p><div class="food-meta"><span><?= e((string)$f['quantity_kg']) ?> kg</span><span><?= e($f['pickup_address']) ?></span></div><p><small>Priority <?= (int)$f['priority_score'] ?>/100 · <?= $f['area_match']?'Area overlap':'Area overlap not detected' ?></small></p><div class="deadline">Safe deadline <b><?= e(date('d M, g:i A',strtotime($f['safety_deadline']))) ?></b></div><form method="post" action="<?= e(url('request_donation.php')) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="food_id" value="<?= (int)$f['id'] ?>"><button class="btn btn-sm" type="submit" <?= $u['role']==='admin'?'disabled':'' ?>>Request food ↗</button></form></div></article><?php endforeach; ?></div><?php if(!$foods): ?><div class="empty-state"><h3>No approved food matches</h3><p>Try another area or check later.</p></div><?php endif; ?>
<?php page_footer(); ?>